  color: var(--text);
  background: var(--bg-panel);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 7px 9px;
  font-family: inherit;
  resize: vertical;
}
.library-import-block textarea {
  min-height: 60px;
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 12px;
}
.library-import-error {
  color: #ef4444;
  font-size: 12px;
}
.library-import-actions {
  display: flex;
  justify-content: flex-end;
  gap: 8px;
}
.library-ds-card {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: stretch;
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  overflow: hidden;
  padding: 10px;
  gap: 10px;
  transition: border-color 160ms cubic-bezier(0.23, 1, 0.32, 1), box-shadow 160ms cubic-bezier(0.23, 1, 0.32, 1), background 160ms cubic-bezier(0.23, 1, 0.32, 1);
}
.library-ds-card.disabled {
  opacity: 0.45;
}
.library-ds-card.highlighted {
  border-color: var(--accent);
  background: var(--accent);
  @supports (color: color-mix(in lab, red, red)) {
    background: color-mix(in srgb, var(--accent) 6%, var(--bg-panel));
  }
  box-shadow: 0 0 0 3px var(--accent);
  @supports (color: color-mix(in lab, red, red)) {
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--accent) 18%, transparent);
  }
}
.library-ds-card-content {
  min-width: 0;
  padding: 2px;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: background 120ms cubic-bezier(0.23, 1, 0.32, 1), box-shadow 120ms cubic-bezier(0.23, 1, 0.32, 1);
}
.library-ds-card-content:hover {
  background: var(--bg-hover);
}
.library-ds-card-content:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--selected-soft);
  background: var(--bg-hover);
}
.library-ds-edit {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  vertical-align: middle;
  width: 22px;
  height: 22px;
  margin-left: 4px;
  padding: 0;
  border: none;
  background: transparent;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  cursor: pointer;
  opacity: 0;
  transition: opacity 160ms cubic-bezier(0.23, 1, 0.32, 1), color 160ms cubic-bezier(0.23, 1, 0.32, 1), background 160ms cubic-bezier(0.23, 1, 0.32, 1);
}
.library-ds-card-content:hover .library-ds-edit, .library-ds-edit:focus-visible {
  opacity: 1;
}
.library-ds-edit:hover {
  color: var(--text);
  background: var(--bg-muted);
}
.library-ds-swatches {
  display: flex;
  gap: 4px;
  margin-bottom: 6px;
}
.library-ds-swatch {
  width: 18px;
  height: 18px;
  border-radius: var(--radius-xs);
  border: 1px solid rgba(128, 128, 128, 0.2);
}
.library-ds-title {
  font-size: 13px;
  font-weight: 600;
  margin-bottom: 2px;
}
.library-ds-summary {
  font-size: 11px;
  color: var(--text-muted);
  line-height: 1.3;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.library-ds-toggle-cell {
  display: flex;
  align-items: flex-start;
  justify-content: center;
  padding-left: 10px;
  border-left: 1px solid var(--border-subtle);
  cursor: default;
}
.library-ds-toggle-cell .toggle-switch {
  margin-top: 1px;
}
.library-preview {
  width: 100%;
  padding: 12px;
  border-top: 1px solid var(--border);
  margin-top: 4px;
}
.library-preview-body {
  font-size: 12px;
  line-height: 1.5;
  white-space: pre-wrap;
  word-break: break-word;
  max-height: 300px;
  overflow-y: auto;
  margin: 0;
  color: var(--text-muted);
}
.library-empty {
  text-align: center;
  color: var(--text-muted);
  font-size: 13px;
  padding: 28px 24px;
  background: var(--bg-subtle);
  border-radius: var(--radius-md, 8px);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}
.library-empty-title {
  margin: 0;
  font-weight: 600;
  color: var(--text);
}
.library-empty-hint {
  margin: 0;
  font-size: 12px;
  max-width: 420px;
  line-height: 1.5;
}
.library-empty-hint code {
  font-family: var(--font-mono);
  font-size: 11.5px;
  padding: 1px 6px;
  background: var(--bg-subtle);
  border-radius: var(--radius-xs);
}
.memory-disabled-banner {
  padding: 8px 12px;
  border-radius: var(--radius);
  background: rgba(255, 159, 64, 0.12);
  color: var(--text-muted, #b06a00);
  border: 1px solid rgba(255, 159, 64, 0.32);
  font-size: 12px;
  margin: 8px 0 12px;
}
.memory-noprovider-banner {
  padding: 8px 12px;
  border-radius: var(--radius);
  background: rgba(220, 53, 69, 0.10);
  color: var(--text-danger, #b02a37);
  border: 1px solid rgba(220, 53, 69, 0.32);
  font-size: 12px;
  margin: 8px 0 12px;
}
.memory-create-section {
  display: grid;
  gap: 10px;
  padding: 14px 16px;
}
.memory-control-head {
  align-items: center;
  gap: 14px;
}
.memory-control-copy {
  min-width: 0;
}
.memory-header-actions {
  display: inline-flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
  flex: 0 0 auto;
}
.memory-top-tabs {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  min-height: 28px;
  padding: 2px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-pill);
  background: var(--bg-subtle);
}
.memory-top-tab {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 22px;
  padding: 0 9px;
  border: 0;
  border-radius: var(--radius-pill);
  background: transparent;
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 620;
  line-height: 1;
  white-space: nowrap;
  cursor: pointer;
  transition: background 140ms cubic-bezier(0.23, 1, 0.32, 1), color 140ms cubic-bezier(0.23, 1, 0.32, 1), box-shadow 140ms cubic-bezier(0.23, 1, 0.32, 1);
}
.memory-top-tab:hover {
  color: var(--text);
}
.memory-top-tab.active {
  background: var(--bg-panel);
  color: var(--text);
  box-shadow: var(--shadow-xs);
}
.memory-icon-action {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius);
  background: var(--bg-panel);
  color: var(--text-muted);
  cursor: pointer;
  transition: background 140ms cubic-bezier(0.23, 1, 0.32, 1), border-color 140ms cubic-bezier(0.23, 1, 0.32, 1), color 140ms cubic-bezier(0.23, 1, 0.32, 1), box-shadow 140ms cubic-bezier(0.23, 1, 0.32, 1);
}
.memory-icon-action:hover, .memory-icon-action:focus-visible {
  border-color: var(--border);
  background: var(--bg-subtle);
  color: var(--text);
  box-shadow: var(--shadow-xs);
}
.memory-how-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 2px;
}
.memory-auto-flow {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 7px;
  width: fit-content;
  max-width: 100%;
  padding: 6px 9px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-pill);
  background: var(--bg-subtle);
  color: var(--text-muted);
  font-size: 11.5px;
  font-weight: 620;
  line-height: 1.2;
}
.memory-auto-flow strong {
  color: var(--text);
}
.memory-how-copy {
  max-width: 780px;
  margin: 0;
  color: var(--text-muted);
  font-size: 12.5px;
  line-height: 1.45;
}
.memory-add-disclosure {
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: var(--bg-panel);
}
.memory-add-summary {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 11px 12px;
  border: 0;
  border-radius: var(--radius-sm);
  background: transparent;
  color: var(--text);
  text-align: left;
  cursor: pointer;
  user-select: none;
}
.memory-add-summary:hover {
  background: var(--bg-subtle);
}
.memory-add-summary-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  background: var(--accent);
  @supports (color: color-mix(in lab, red, red)) {
    background: color-mix(in oklab, var(--accent) 10%, var(--bg-panel));
  }
  color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
  @supports (color: color-mix(in lab, red, red)) {
    box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--accent) 18%, var(--border-soft));
  }
}
.memory-add-summary-copy {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.memory-add-summary-copy strong {
  font-size: 13px;
  font-weight: 650;
  line-height: 1.2;
  color: var(--text);
}
.memory-add-summary-copy small {
  font-size: 11px;
  color: var(--text-muted);
  line-height: 1.2;
}
.memory-add-summary-chevron {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  color: var(--text-muted);
  transition: transform 160ms cubic-bezier(0.23, 1, 0.32, 1);
}
.memory-add-summary.is-open .memory-add-summary-chevron {
  transform: rotate(180deg);
}
.memory-add-disclosure-body {
  display: flex;
  flex-direction: column;
  gap: 12px;
  padding: 0 12px 12px;
  border-top: 1px solid var(--border-soft);
  padding-top: 12px;
}
.memory-action-modal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1700;
  display: grid;
  place-items: center;
  padding: 0;
  background: var(--overlay-scrim, rgba(0, 0, 0, 0.42));
  @supports (color: color-mix(in lab, red, red)) {
    background: color-mix(in srgb, var(--overlay-scrim, rgba(0, 0, 0, 0.42)) 72%, transparent);
  }
}
.memory-action-modal {
  display: flex;
  flex-direction: column;
  width: min(920px, calc(100vw - 48px));
  height: min(720px, calc(100vh - 64px));
  max-height: min(720px, calc(100vh - 64px));
  overflow: hidden;
  border: 1px solid var(--border-soft);
  border-radius: 14px;
  background: var(--bg-panel);
  box-shadow: 0 22px 70px var(--shadow-color, #000);
  @supports (color: color-mix(in lab, red, red)) {
    box-shadow: 0 22px 70px color-mix(in srgb, var(--shadow-color, #000) 22%, transparent);
  }
}
.memory-action-modal--advanced {
  width: min(920px, calc(100vw - 48px));
}
.memory-action-modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px 12px;
  border-bottom: 1px solid var(--border-soft);
}
.memory-action-modal-head h3 {
  margin: 0;
  font-size: 15px;
  line-height: 1.25;
}
.memory-action-modal-head p {
  margin: 3px 0 0;
  color: var(--text-muted);
  font-size: 12.5px;
  line-height: 1.4;
}
.memory-action-modal-close {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
  width: 30px;
  height: 30px;
  padding: 0;
  border: 1px solid var(--border-soft);
  border-radius: 50%;
  background: var(--bg-panel);
  color: var(--text-muted);
  cursor: pointer;
  transition: background 140ms cubic-bezier(0.23, 1, 0.32, 1), border-color 140ms cubic-bezier(0.23, 1, 0.32, 1), color 140ms cubic-bezier(0.23, 1, 0.32, 1);
}
.memory-action-modal-close:hover, .memory-action-modal-close:focus-visible {
  border-color: var(--border);
  background: var(--bg-subtle);
  color: var(--text);
}
.memory-action-modal-body {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  gap: 12px;
  min-height: 0;
  overflow: auto;
  padding: 14px 18px 18px;
}
.memory-action-modal button.primary, .memory-action-modal button.ghost {
  align-items: center;
  justify-content: center;
  text-align: center;
}
.memory-advanced-modal-body {
  gap: 10px;
}
.memory-work-profile {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 14px;
  align-items: center;
  margin-top: 4px;
  padding: 14px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: var(--bg-panel);
}
.memory-work-profile-copy {
  display: grid;
  gap: 5px;
  min-width: 0;
}
.memory-kicker {
  color: var(--text-muted);
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0;
  line-height: 1.2;
  text-transform: uppercase;
}
.memory-work-profile h4, .memory-gateway-card h4 {
  margin: 0;
  color: var(--text);
  font-size: 15px;
  line-height: 1.25;
}
.memory-work-profile p {
  max-width: 680px;
  margin: 0;
  color: var(--text-muted);
  font-size: 12.5px;
  line-height: 1.45;
}
.memory-brief-flow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 34px;
  padding: 5px 8px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-pill);
  background: var(--bg-subtle);
  color: var(--text-muted);
  font-size: 11px;
  font-weight: 650;
  white-space: nowrap;
}
.memory-brief-flow span:last-child {
  color: var(--text);
}
.memory-guide-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}
.memory-guide-card, .memory-scenario-card {
  color: var(--text);
  text-align: left;
  cursor: pointer;
  transition: background 160ms cubic-bezier(0.23, 1, 0.32, 1), border-color 160ms cubic-bezier(0.23, 1, 0.32, 1), box-shadow 160ms cubic-bezier(0.23, 1, 0.32, 1);
}
.memory-guide-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 10px;
  min-height: 128px;
  padding: 12px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: var(--bg-panel);
}
.memory-guide-card:hover, .memory-scenario-card:hover {
  border-color: var(--border);
  background: var(--bg-panel);
  @supports (color: color-mix(in lab, red, red)) {
    background: color-mix(in oklab, var(--bg-panel) 78%, var(--bg-subtle));
  }
  box-shadow: var(--shadow-xs);
}
.memory-guide-icon, .memory-scenario-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 28px;
  height: 28px;
  border-radius: var(--radius-sm);
  background: var(--accent);
  @supports (color: color-mix(in lab, red, red)) {
    background: color-mix(in oklab, var(--accent) 10%, var(--bg-panel));
  }
  color: var(--accent);
  box-shadow: inset 0 0 0 1px var(--accent);
  @supports (color: color-mix(in lab, red, red)) {
    box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--accent) 18%, var(--border-soft));
  }
}
.memory-guide-copy {
  display: grid;
  gap: 5px;
  min-width: 0;
}
.memory-guide-step {
  color: var(--text-muted);
  font-size: 10px;
  font-weight: 700;
  line-height: 1.2;
  text-transform: uppercase;
}
.memory-guide-copy strong, .memory-scenario-card strong {
  color: var(--text);
  font-size: 13px;
  line-height: 1.25;
}
.memory-guide-copy small, .memory-scenario-card small {
  color: var(--text-muted);
  font-size: 11.5px;
  line-height: 1.35;
}
.memory-guide-cta {
  align-self: end;
  color: var(--accent);
  font-size: 11px;
  font-weight: 700;
  line-height: 1.2;
}
.memory-gateway-card, .memory-scenario-section {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: var(--bg-panel);
}
.memory-gateway-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}
.memory-gateway-head > div {
  display: grid;
  gap: 4px;
}
.memory-gateway-example {
  display: grid;
  grid-template-columns: minmax(0, 0.78fr) minmax(0, 1.22fr);
  gap: 10px;
}
.memory-gateway-example > div {
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 11px 12px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: var(--bg-subtle);
}
.memory-example-label {
  color: var(--text-muted);
  font-size: 10.5px;
  font-weight: 700;
  line-height: 1.2;
  text-transform: uppercase;
}
.memory-gateway-example p {
  margin: 0;
  color: var(--text);
  font-size: 13px;
  line-height: 1.4;
}
.memory-gateway-example pre {
  overflow-x: auto;
  margin: 0;
  color: var(--text);
  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  font-size: 11px;
  line-height: 1.45;
  white-space: pre;
}
.memory-scenario-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}
.memory-scenario-card {
  display: grid;
  gap: 7px;
  min-height: 154px;
  padding: 11px 12px;
  border: 1px solid var(--border-soft);
  border-radius: var(--radius-sm);
  background: var(--bg-subtle);
}
.memory-scenario-topline {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 7px;
  align-items: center;
  min-width: 0;
}
.memory-scenario-label, .memory-scenario-count {
  overflow: hidden;
  color: var(--text-muted);
